242	+// profileJudges resolves the panel of judges and the index of the chair (the
243	+// judge that merges a multi-judge panel; 0 for a single judge). Resolution
244	+// order: explicit Judges, then the legacy standalone MasterAgent, then the
245	+// legacy worker Master. Returns an empty slice when the profile has no judge.
246	+func profileJudges(profile settings.ReviewProfileConfig) ([]judgeSpec, int) {
247	+	if len(profile.Judges) > 0 {
248	+		judges := make([]judgeSpec, 0, len(profile.Judges))
249	+		for _, cfg := range profile.Judges {
250	+			name := strings.TrimSpace(cfg.Agent)
251	+			if name == "" {
252	+				continue
253	+			}
254	+			judges = append(judges, judgeSpec{agent: name, model: strings.TrimSpace(cfg.Model)})
255	+		}
256	+		if len(judges) == 0 {
257	+			return nil, 0
258	+		}
259	+		chair := 0
260	+		if sel := strings.TrimSpace(profile.Chair); sel != "" {
261	+			for i, j := range judges {
262	+				if j.agent == sel || j.agent+":"+j.model == sel {
263	+					chair = i
264	+					break
265	+				}
266	+			}
267	+		}
268	+		return judges, chair
269	+	}
270	+	if ma := strings.TrimSpace(profile.MasterAgent); ma != "" {
271	+		return []judgeSpec{{agent: ma, model: strings.TrimSpace(profile.MasterModel)}}, 0
272	+	}
273	+	if workerName, cfg, err := selectProfileWorker(profile, profile.Master); err == nil {
274	+		model := strings.TrimSpace(profile.MasterModel)
275	+		if model == "" {
276	+			model = strings.TrimSpace(cfg.Model)
277	+		}
278	+		return []judgeSpec{{agent: reviewAgentName(workerName, cfg), model: model}}, 0
279	+	}
280	+	return nil, 0
281	+}
