284	+// single judge) and whether the profile has any judge. Kept for callers that
285	+// need a single "who decides" identity (validation, labels, picker preselect).
286	+func profileMasterIdentity(profile settings.ReviewProfileConfig) (string, string, bool) {
287	+	judges, chair := profileJudges(profile)
288	+	if len(judges) == 0 {
289	+		return "", "", false
290	+	}
291	+	if chair < 0 || chair >= len(judges) {
292	+		chair = 0
293	+	}
294	+	return judges[chair].agent, judges[chair].model, true
