305	+func selectProfileWorker(profile settings.ReviewProfileConfig, selector string) (string, settings.ReviewConfig, error) {
306	+	selector = strings.TrimSpace(selector)
307	+	if selector == "" {
308	+		return "", settings.ReviewConfig{}, errors.New("empty review inspector selector")
309	+	}
310	+	if cfg, ok := profile.Agents[selector]; ok && !cfg.IsZero() {
311	+		return selector, cfg, nil
312	+	}
313	+	var matches []string
314	+	for workerName, cfg := range profile.Agents {
315	+		if cfg.IsZero() {
316	+			continue
317	+		}
318	+		if reviewAgentName(workerName, cfg) == selector {
319	+			matches = append(matches, workerName)
320	+		}
321	+	}
322	+	sort.Strings(matches)
323	+	switch len(matches) {
324	+	case 1:
325	+		return matches[0], profile.Agents[matches[0]], nil
326	+	case 0:
327	+		configured := sortedProfileAgentNames(profile)
328	+		if len(configured) == 0 {
329	+			return "", settings.ReviewConfig{}, fmt.Errorf("review inspector or agent %q is not configured", selector)
330	+		}
331	+		return "", settings.ReviewConfig{}, fmt.Errorf("review inspector or agent %q is not configured; configured inspectors: %s", selector, strings.Join(configured, ", "))
332	+	default:
333	+		return "", settings.ReviewConfig{}, fmt.Errorf("agent %q has multiple review inspectors (%s); choose one by inspector name", selector, strings.Join(matches, ", "))
334	+	}
335	+}
