337	+func workerIDForAgentModel(agentName, model string, existing map[string]settings.ReviewConfig) string {
338	+	base := strings.TrimSpace(agentName)
339	+	if strings.TrimSpace(model) != "" {
340	+		base += ":" + sanitizeWorkerIDPart(model)
341	+	}
342	+	if base == "" {
343	+		base = "worker"
344	+	}
345	+	candidate := base
346	+	for i := 2; ; i++ {
347	+		if _, exists := existing[candidate]; !exists {
348	+			return candidate
349	+		}
350	+		candidate = fmt.Sprintf("%s-%d", base, i)
351	+	}
352	+}
353	+
354	+func sanitizeWorkerIDPart(s string) string {
355	+	s = strings.ToLower(strings.TrimSpace(s))
356	+	var b strings.Builder
357	+	lastDash := false
358	+	for _, r := range s {
359	+		keep := (r >= 'a' && r <= 'z') || (r >= '0' && r <= '9')
360	+		if keep {
361	+			b.WriteRune(r)
362	+			lastDash = false
363	+			continue
364	+		}
365	+		if !lastDash {
366	+			b.WriteByte('-')
367	+			lastDash = true
368	+		}
369	+	}
370	+	out := strings.Trim(b.String(), "-")
371	+	if out == "" {
372	+		return "model"
373	+	}
374	+	return out
375	+}
