521	+// PanelSynthesisProvider runs a panel of judges over the inspectors' reports.
522	+// Each judge independently produces a verdict from the same synthesis prompt;
523	+// when two or more verdicts come back, the chair judge merges them into one
524	+// final verdict and the individual verdicts are appended as a panel.
525	+//
526	+// It implements SynthesisProvider, so the existing SynthesisSink uses it
527	+// unchanged — a panel is just a provider that happens to consult several
528	+// judges. A single judge collapses to that judge's verdict (today's behavior).
529	+type PanelSynthesisProvider struct {
530	+	Judges   []SynthesisProvider // one per judge; index aligns with Labels
531	+	Labels   []string            // display label per judge (e.g. "codex · gpt-5")
532	+	ChairIdx int                 // index of the judge that merges the panel
533	+}
534	+
535	+// Synthesize fans out to each judge in parallel, then has the chair merge the
536	+// verdicts. Failed judges are dropped; if only one verdict survives it is
537	+// returned directly. If every judge fails, the error is returned so the caller
538	+// can report "final report unavailable".
539	+func (p PanelSynthesisProvider) Synthesize(ctx context.Context, prompt string) (string, error) {
540	+	switch len(p.Judges) {
541	+	case 0:
542	+		return "", errors.New("no judges configured")
543	+	case 1:
544	+		return p.Judges[0].Synthesize(ctx, prompt) //nolint:wrapcheck // transparent single-judge passthrough
545	+	}
546	+
547	+	verdicts := make([]string, len(p.Judges))
548	+	errs := make([]error, len(p.Judges))
549	+	var wg sync.WaitGroup
550	+	for i := range p.Judges {
551	+		wg.Add(1)
552	+		go func(i int) {
553	+			defer wg.Done()
554	+			verdicts[i], errs[i] = p.Judges[i].Synthesize(ctx, prompt)
555	+		}(i)
556	+	}
557	+	wg.Wait()
558	+
559	+	ok := make([]int, 0, len(p.Judges))
560	+	for i := range verdicts {
561	+		if errs[i] == nil && strings.TrimSpace(verdicts[i]) != "" {
562	+			ok = append(ok, i)
563	+		}
564	+	}
565	+	switch len(ok) {
566	+	case 0:
567	+		return "", fmt.Errorf("all judges failed: %w", firstNonNilErr(errs))
568	+	case 1:
