572	+	// Pick the chair; fall back to the first successful judge if the configured
573	+	// chair failed or is out of range. The chair participates as a full panel
574	+	// judge (it produced its own verdict above) and then runs a second time to
575	+	// merge the panel — these are deliberately distinct calls: an independent
576	+	// verdict, then a reconciliation over all verdicts.
577	+	chair := p.ChairIdx
578	+	if chair < 0 || chair >= len(p.Judges) || errs[chair] != nil || strings.TrimSpace(verdicts[chair]) == "" {
579	+		chair = ok[0]
580	+	}
581	+
582	+	final, err := p.Judges[chair].Synthesize(ctx, composeChairPrompt(verdicts, p.Labels, ok))
