584	+		// Chair merge failed: surface the panel rather than nothing.
585	+		final = "The judges could not be merged into a single verdict; see each judge's verdict below."
586	+	}
587	+
588	+	var b strings.Builder
589	+	b.WriteString(strings.TrimSpace(final))
590	+	b.WriteString("\n\n## Panel\n\n")
591	+	for _, i := range ok {
592	+		fmt.Fprintf(&b, "### %s\n\n%s\n\n", p.labelAt(i), strings.TrimSpace(verdicts[i]))
593	+	}
594	+	return b.String(), nil
