package review

import (
	"context"
	"testing"

	"github.com/entireio/cli/cmd/entire/cli/agent"
	reviewtypes "github.com/entireio/cli/cmd/entire/cli/review/types"
	"github.com/entireio/cli/cmd/entire/cli/settings"
)

const (
	tAgentClaude = "claude-code"
	tAgentCodex  = "codex"
	tModelOpus   = "opus"
	tModelSonnet = "sonnet"
